import{b as d,O as r,g as e,j as o}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"测试分类","description":"","frontmatter":{},"headers":[],"relativePath":"testing/appendix/test-classification/index.md","filePath":"测试理论与实践/7.附录：模板与核心概念/05.测试分类.md","lastUpdated":1781625968000}'),a={name:"testing/appendix/test-classification/index.md"};function n(s,t,h,l,i,g){return r(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="测试分类" tabindex="-1">测试分类 <a class="header-anchor" href="#测试分类" aria-label="Permalink to &quot;测试分类&quot;">​</a></h1><blockquote><p>冒烟测试、回归测试、系统测试、集成测试……这些概念不是同一层的，搞混是因为把三个维度的分类标准混在一起比了。</p></blockquote><h2 id="为什么容易搞混" tabindex="-1">为什么容易搞混 <a class="header-anchor" href="#为什么容易搞混" aria-label="Permalink to &quot;为什么容易搞混&quot;">​</a></h2><p>因为日常交流中这些词经常随意混用——&quot;这轮做一下回归测试&quot;实际说的是&quot;这轮重跑一遍系统功能测试&quot;。说的人知道自己在说什么，听的人以为回归测试和功能测试是平级概念。</p><p>实际上测试分类有五个独立维度：<strong>级别</strong>（测多大范围）、<strong>目的</strong>（为什么测）、<strong>类型</strong>（测什么属性）、<strong>方法</strong>（怎么看代码）、<strong>执行形态</strong>（人跑还是机器跑）。一个测试活动可以同时属于五个维度。</p><p>先看全景：</p><table tabindex="0"><thead><tr><th>维度</th><th>回答的问题</th><th>常见成员</th></tr></thead><tbody><tr><td><strong>测试级别</strong></td><td>测多大范围？从哪到哪？</td><td>单元测试、集成测试、系统测试、验收测试（α/β/UAT）</td></tr><tr><td><strong>测试目的</strong></td><td>这一轮为什么测？</td><td>冒烟测试、回归测试、探索式测试、基准测试</td></tr><tr><td><strong>测试类型</strong></td><td>关注什么质量属性？</td><td>功能测试、性能测试、安全测试、兼容性测试、可用性测试</td></tr><tr><td><strong>测试方法</strong></td><td>怎么看代码来设计用例？</td><td>黑盒测试、白盒测试、灰盒测试</td></tr><tr><td><strong>执行形态</strong></td><td>人跑还是机器跑？跑不跑代码？</td><td>静态测试、动态手工测试、动态自动化测试</td></tr></tbody></table><blockquote><p>五个维度不是互斥的——&quot;用黑盒方法对支付模块写自动化脚本，做系统级别的回归功能测试&quot;同时命中了方法（黑盒）、执行形态（自动化）、级别（系统）、目的（回归）、类型（功能）。</p></blockquote><hr><h2 id="一、测试级别-范围从哪到哪" tabindex="-1">一、测试级别：范围从哪到哪 <a class="header-anchor" href="#一、测试级别-范围从哪到哪" aria-label="Permalink to &quot;一、测试级别：范围从哪到哪&quot;">​</a></h2><p>按测试覆盖的范围从小到大排列：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单元测试 ──→ 集成测试 ──→ 系统测试 ──→ 验收测试</span></span>
<span class="line"><span>(一个函数)   (几个模块)   (整个系统)   (用户来验)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>级别</th><th>测什么</th><th style="text-align:center;">谁来测</th><th>依赖</th><th style="text-align:center;">速度</th></tr></thead><tbody><tr><td><strong>单元测试</strong></td><td>单个函数/类/方法</td><td style="text-align:center;">开发</td><td>无外部依赖</td><td style="text-align:center;">毫秒级</td></tr><tr><td><strong>集成测试</strong></td><td>模块间交互、接口调用</td><td style="text-align:center;">开发/测试</td><td>需数据库/文件/网络</td><td style="text-align:center;">秒级</td></tr><tr><td><strong>系统测试</strong></td><td>完整系统端到端</td><td style="text-align:center;">测试</td><td>完整部署环境</td><td style="text-align:center;">分钟级</td></tr><tr><td><strong>验收测试</strong></td><td>业务场景是否符合预期</td><td style="text-align:center;">产品/用户</td><td>类生产环境</td><td style="text-align:center;">分钟级</td></tr></tbody></table><blockquote><p>具体说明见<a href="/testing/methodology/white-black-box.html">白盒与黑盒</a>中的测试金字塔章节——70% 单元 + 20% 集成 + 10% 系统/验收。</p></blockquote><p>验收测试按执行环境和参与人员可以进一步拆成三种：</p><table tabindex="0"><thead><tr><th>验收类型</th><th>谁来做</th><th>在哪做</th><th>目的</th><th>特点</th></tr></thead><tbody><tr><td><strong>α 测试</strong></td><td>内部团队（非开发/测试人员）</td><td>公司内部受控环境</td><td>在发布给外部用户前，内部先过一遍</td><td>开发可以在旁边观察和修 Bug</td></tr><tr><td><strong>β 测试</strong></td><td>真实外部用户/种子用户</td><td>用户真实环境</td><td>在真实使用场景中发现问题</td><td>无法控制用户行为，但能发现想不到的问题</td></tr><tr><td><strong>UAT（用户验收测试）</strong></td><td>客户/甲方/业务方</td><td>类生产环境</td><td>确认系统满足合同或业务需求</td><td>偏商务确认，按验收标准逐条过</td></tr></tbody></table><blockquote><p>α 和 β 的区别一句话：<strong>α 在公司里测，β 放出去给用户测。</strong> α 发现的是&quot;我们没测到的&quot;，β 发现的是&quot;没想到用户还能这么用&quot;。</p></blockquote><hr><h2 id="二、测试目的-为什么测这一轮" tabindex="-1">二、测试目的：为什么测这一轮 <a class="header-anchor" href="#二、测试目的-为什么测这一轮" aria-label="Permalink to &quot;二、测试目的：为什么测这一轮&quot;">​</a></h2><p>同一个系统测试，可以是冒烟（快速过一下）、也可以是回归（确认改动没搞坏别的）、也可以是基准（建立性能参照线）。</p><table tabindex="0"><thead><tr><th>目的</th><th>一句话</th><th>什么时候做</th><th>特点</th></tr></thead><tbody><tr><td><strong>冒烟测试</strong></td><td>快速验一下能不能往下测</td><td>新版本部署后、提测后</td><td>只跑核心流程，5~30 分钟，不过就打回</td></tr><tr><td><strong>回归测试</strong></td><td>改了 A，确认 B、C、D 没坏</td><td>每次代码变更后</td><td>跑已有的用例，范围取决于改动影响面</td></tr><tr><td><strong>探索式测试</strong></td><td>边测边学边设计用例</td><td>对功能有初步了解后</td><td>不按预设用例，依赖测试人员经验和直觉</td></tr><tr><td><strong>基准测试</strong></td><td>建立性能参照线</td><td>系统稳定后、优化前后对比</td><td>固定条件重复跑，关注数值变化</td></tr><tr><td><strong>重测</strong></td><td>验证上次失败的用例这次好了没</td><td>Bug 修复后</td><td>只跑之前失败的那几条</td></tr></tbody></table><h3 id="冒烟-vs-回归-最容易搞混的两个" tabindex="-1">冒烟 vs 回归：最容易搞混的两个 <a class="header-anchor" href="#冒烟-vs-回归-最容易搞混的两个" aria-label="Permalink to &quot;冒烟 vs 回归：最容易搞混的两个&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>冒烟测试</th><th>回归测试</th></tr></thead><tbody><tr><td><strong>目的</strong></td><td>判断能不能往下测</td><td>确认改动没引入新问题</td></tr><tr><td><strong>时机</strong></td><td>每次新版本/新提测开始时</td><td>每次代码变更后</td></tr><tr><td><strong>范围</strong></td><td>只跑核心流程，窄而精</td><td>跑已有用例，范围取决于改动影响面</td></tr><tr><td><strong>时间</strong></td><td>5~30 分钟</td><td>几小时到几天</td></tr><tr><td><strong>不过怎么办</strong></td><td>打回，不值得深入测</td><td>提 Bug，修完再回归</td></tr></tbody></table><blockquote><p>冒烟不通过 → 这个版本不值得花时间测。回归不通过 → 这次改动搞坏了别的东西。</p></blockquote><hr><h2 id="三、测试类型-关注什么质量属性" tabindex="-1">三、测试类型：关注什么质量属性 <a class="header-anchor" href="#三、测试类型-关注什么质量属性" aria-label="Permalink to &quot;三、测试类型：关注什么质量属性&quot;">​</a></h2><p>不管测什么级别、出于什么目的，总要关注某一个质量方面：</p><table tabindex="0"><thead><tr><th>类型</th><th>关注点</th><th>例子</th></tr></thead><tbody><tr><td><strong>功能测试</strong></td><td>功能对不对</td><td>登录成功跳转首页了吗？搜索返回正确结果了吗？</td></tr><tr><td><strong>性能测试</strong></td><td>系统快不快、稳不稳</td><td>500 并发下 P95 &lt; 500ms？内存有没有泄漏？</td></tr><tr><td><strong>安全测试</strong></td><td>安全机制是否有效</td><td>权限校验？加密传输？会话不过期？</td></tr><tr><td><strong>渗透测试</strong></td><td>模拟攻击能不能打进来</td><td>模拟黑客攻击，尝试突破系统防御</td></tr><tr><td><strong>兼容性测试</strong></td><td>不同环境能不能用</td><td>Chrome/Safari/Firefox？iOS/Android？</td></tr><tr><td><strong>可用性测试</strong></td><td>好不好用</td><td>用户能 3 步完成下单吗？错误提示看得懂吗？</td></tr><tr><td><strong>可靠性测试</strong></td><td>容不容易挂</td><td>连续跑 24 小时？断电恢复后数据还在吗？</td></tr></tbody></table><hr><h2 id="四、测试方法-怎么看代码" tabindex="-1">四、测试方法：怎么看代码 <a class="header-anchor" href="#四、测试方法-怎么看代码" aria-label="Permalink to &quot;四、测试方法：怎么看代码&quot;">​</a></h2><p>不管测什么级别、什么目的、什么类型，总要选一个<strong>设计用例的视角</strong>——看源码还是不看源码。</p><table tabindex="0"><thead><tr><th>方法</th><th>一句话</th><th style="text-align:center;">是否看源码</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>黑盒测试</strong></td><td>不看代码，只关心输入输出对不对</td><td style="text-align:center;">否</td><td>功能测试、验收测试——从用户视角出发</td></tr><tr><td><strong>白盒测试</strong></td><td>打开代码，确保每条路径都走过</td><td style="text-align:center;">是</td><td>单元测试、代码审查——从实现视角出发</td></tr><tr><td><strong>灰盒测试</strong></td><td>了解内部结构但不逐行看代码</td><td style="text-align:center;">部分</td><td>接口测试、集成测试——知道数据怎么流就够了</td></tr></tbody></table><blockquote><p>黑盒发现需求理解层面的问题（功能做对了吗），白盒发现实现层面的问题（代码逻辑对吗），两者互补不是对立。详细方法见<a href="/testing/methodology/white-black-box.html">白盒与黑盒</a>。</p></blockquote><p>黑盒测试为什么容易跟其他概念混在一起？因为它几乎总是和&quot;系统测试 + 功能测试&quot;一起出现——但这不等于它们是同一回事。你完全可以在单元测试里用黑盒方法（只看函数输出不看内部实现），也完全可以在系统测试里用白盒方法（虽然很少这么做）。</p><hr><h2 id="五、执行形态-人跑还是机器跑-跑不跑代码" tabindex="-1">五、执行形态：人跑还是机器跑，跑不跑代码 <a class="header-anchor" href="#五、执行形态-人跑还是机器跑-跑不跑代码" aria-label="Permalink to &quot;五、执行形态：人跑还是机器跑，跑不跑代码&quot;">​</a></h2><p>这其实是两层划分，放在一起讲更清晰：</p><h3 id="静态-vs-动态-跑不跑代码" tabindex="-1">静态 vs 动态：跑不跑代码 <a class="header-anchor" href="#静态-vs-动态-跑不跑代码" aria-label="Permalink to &quot;静态 vs 动态：跑不跑代码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th style="text-align:center;">是否执行代码</th><th>做什么</th><th>典型工具</th></tr></thead><tbody><tr><td><strong>静态测试</strong></td><td style="text-align:center;">否</td><td>不运行程序，通过审查文档/代码、静态分析来发现缺陷</td><td>SonarQube、ESLint、Checkstyle</td></tr><tr><td><strong>动态测试</strong></td><td style="text-align:center;">是</td><td>运行程序，观察实际输出与预期是否一致</td><td>JUnit、JMeter、Selenium</td></tr></tbody></table><blockquote><p>静态测试是很多团队最容易忽略的维度——&quot;代码审查算测试吗？&quot;算。而且静态分析能在代码还没跑起来之前就发现空指针、资源泄漏等问题，成本远低于动态测试。</p></blockquote><h3 id="手工-vs-自动化-人跑还是机器跑-仅动态测试" tabindex="-1">手工 vs 自动化：人跑还是机器跑（仅动态测试） <a class="header-anchor" href="#手工-vs-自动化-人跑还是机器跑-仅动态测试" aria-label="Permalink to &quot;手工 vs 自动化：人跑还是机器跑（仅动态测试）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>执行方式</th><th>谁来做</th><th>适用场景</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>手工测试</strong></td><td>人</td><td>探索式、一次性、体验类</td><td>新产品体验走查、UI 视觉验收</td></tr><tr><td><strong>自动化测试</strong></td><td>脚本/工具</td><td>重复性、回归类、大数据量</td><td>CI 自动跑单元测试、接口回归、压测</td></tr></tbody></table><blockquote><p>&quot;验收测试就是手工测试&quot;——这是最常见的误解。验收测试是<strong>级别</strong>，手工是<strong>执行形态</strong>，验收测试完全可以自动化（比如用 Selenium 跑验收用例）。</p></blockquote><p>三个形态不是孤立的，一个项目的测试策略通常会全部用到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>静态测试     → 代码提交前：SonarQube 扫代码规范 + Code Review</span></span>
<span class="line"><span>动态自动化   → 代码提交后：CI 自动跑单元测试 + 接口测试</span></span>
<span class="line"><span>动态手工     → 提测后：测试人员手工做探索式测试和验收</span></span></code></pre></div><hr><h2 id="六、五个维度的组合" tabindex="-1">六、五个维度的组合 <a class="header-anchor" href="#六、五个维度的组合" aria-label="Permalink to &quot;六、五个维度的组合&quot;">​</a></h2><p>现实中的测试活动都是五维组合。常见搭配：</p><table tabindex="0"><thead><tr><th>组合</th><th>实际例子</th></tr></thead><tbody><tr><td>静态 + 白盒 + 单元</td><td>SonarQube 扫描代码 + Code Review 检查逻辑</td></tr><tr><td>自动化 + 白盒 + 单元 + 回归</td><td>CI 每次提交自动跑全量单元测试，覆盖所有代码分支</td></tr><tr><td>自动化 + 黑盒 + 系统 + 回归 + 功能</td><td>改了支付模块，CI 自动重跑端到端下单流程</td></tr><tr><td>手工 + 黑盒 + 系统 + 冒烟</td><td>新版本部署后，人工快速验证核心用户流程</td></tr><tr><td>手工 + 黑盒 + 验收 + 探索式</td><td>产品经理在预发布环境随意操作，发现体验问题</td></tr></tbody></table><blockquote><p>写测试计划时，测试策略表里填的就是五维组合。&quot;功能测试：黑盒等价类 + 场景法，自动化执行&quot;——就是&quot;自动化 + 黑盒 + 系统级别 + 功能类型&quot;。</p></blockquote><hr><h2 id="常见混淆场景" tabindex="-1">常见混淆场景 <a class="header-anchor" href="#常见混淆场景" aria-label="Permalink to &quot;常见混淆场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>混淆</th><th>为什么不对</th><th>正确理解</th></tr></thead><tbody><tr><td>&quot;冒烟和回归哪个范围更大？&quot;</td><td>它们回答不同问题，不能比大小</td><td>冒烟看&quot;能不能往下&quot;，回归看&quot;有没有搞坏别的&quot;</td></tr><tr><td>&quot;功能测试属于系统测试吗？&quot;</td><td>功能测试是一种类型，不绑定级别</td><td>功能测试可以发生在任何级别：单元功能、接口功能、系统功能</td></tr><tr><td>&quot;性能测试就是系统测试&quot;</td><td>同上的问题</td><td>单元也可以做性能测试（某个函数的执行耗时）</td></tr><tr><td>&quot;验收测试就是手工测试&quot;</td><td>验收是级别，手工是执行方式</td><td>验收测试可以自动化，单元测试也可以手工跑</td></tr></tbody></table><hr><h2 id="术语速查-听到一个词怎么定位" tabindex="-1">术语速查：听到一个词怎么定位 <a class="header-anchor" href="#术语速查-听到一个词怎么定位" aria-label="Permalink to &quot;术语速查：听到一个词怎么定位&quot;">​</a></h2><p>日常听到的测试术语，快速对应到五维框架的位置：</p><table tabindex="0"><thead><tr><th>听到的词</th><th>所属维度</th><th>定位</th></tr></thead><tbody><tr><td>单元测试、集成测试、系统测试、验收测试</td><td>级别</td><td>四级递进，范围从小到大</td></tr><tr><td>α 测试、β 测试、UAT</td><td>级别 → 验收测试</td><td>验收测试按&quot;谁来测&quot;细分</td></tr><tr><td>接口测试、API 测试</td><td>级别 → 集成测试</td><td>测模块间接口，属于集成测试</td></tr><tr><td>UI 测试、端到端测试</td><td>级别 → 系统测试</td><td>测完整用户界面流程</td></tr><tr><td>冒烟测试、回归测试、探索式测试</td><td>目的</td><td>回答&quot;为什么测这一轮&quot;</td></tr><tr><td>猴子测试</td><td>目的 → 探索式</td><td>随机输入/操作，探索式的极端变体</td></tr><tr><td>功能测试、性能测试、安全测试</td><td>类型</td><td>回答&quot;关注什么质量属性&quot;</td></tr><tr><td>压力测试、负载测试、基准测试</td><td>类型 → 性能测试</td><td>性能测试按不同关注点的细分</td></tr><tr><td>渗透测试</td><td>类型</td><td>模拟真实攻击，和安全测试并列，侧重&quot;攻&quot;而非&quot;防&quot;</td></tr><tr><td>兼容性测试、可用性测试、可靠性测试</td><td>类型</td><td>其他质量属性</td></tr><tr><td>黑盒、白盒、灰盒</td><td>方法</td><td>回答&quot;怎么看代码来设计用例&quot;</td></tr><tr><td>静态分析、代码审查</td><td>执行形态 → 静态</td><td>不运行代码的测试</td></tr><tr><td>手工测试、自动化测试</td><td>执行形态 → 动态</td><td>运行代码的两种执行方式</td></tr><tr><td>A/B 测试、金丝雀发布</td><td>—</td><td>不属于测试分类，是产品实验/发布策略</td></tr><tr><td>契约测试、快照测试</td><td>级别</td><td>特定场景技术，分别属于集成测试和单元测试</td></tr></tbody></table><blockquote><p>遇到没听过的测试术语，先问&quot;它回答的是哪个维度的问题&quot;——大概率就能定位到正确位置。</p></blockquote><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试分类有五个独立维度：<strong>级别</strong>（范围）、<strong>目的</strong>（为什么）、<strong>类型</strong>（测什么属性）、<strong>方法</strong>（怎么看代码）、<strong>执行形态</strong>（人跑还是机器跑）</li><li>五个维度不是互斥概念——一次测试同时属于五个维度，组合起来才完整描述</li><li>静态测试不运行代码（代码审查、静态分析），和动态测试不在一个层面，但都属于测试活动</li><li>自动化/手工是<strong>执行形态</strong>维度，任何级别都可以自动化或手工——&quot;验收测试就是手工测试&quot;是错误的</li><li>写测试策略时，本质上就是在填五维组合：什么执行形态 + 什么方法 + 什么级别 + 什么目的 + 什么类型</li></ol>`,61)])])}const c=d(a,[["render",n]]);export{u as __pageData,c as default};
